    from collections import deque

    queue = deque([(h, t, 0)])
    visited = set()
    visited.add((h, t))

    while queue:
        current_h, current_t, blows = queue.popleft()

        if current_h == 0 and current_t == 0:
            return True, blows

        # Try cutting heads
        for i in range(1, min(current_h, len(head_growth)) + 1):
            new_h = max(0, current_h - i + head_growth[i][0])
            new_t = max(0, current_t + head_growth[i][1])
